1	/**
2	 * @file main.c
3	 * @brief lvgl_sim 入口：参数解析 → LVGL 初始化 → 场景 → 主循环。
4	 *
5	 *   ./lvgl_sim                       # 默认 demo 场景，240x320 @2x 窗口
6	 *   ./lvgl_sim --scene vmap          # vmap 底图 mock
7	 *   ./lvgl_sim --scale 3             # 放大到 3 倍
8	 *   ./lvgl_sim --headless --frames 40 --shot out.png
9	 */
10	
11	#include <getopt.h>
12	#include <stdio.h>
13	#include <stdlib.h>
14	#include <string.h>
15	#include <unistd.h>
16	
17	#include "sim.h"
18	
19	uint32_t sim_tick_ms(void);
20	
21	static uint32_t s_vtick;
22	
23	static uint32_t vtick_get(void)
24	{
25	    return s_vtick;
26	}
27	
28	static const char *const kUsageLines[] = {
29	    "用法: lvgl_sim [选项]",
30	    "  -s, --scene NAME    场景（demo | vmap），默认 demo",
31	    "  -S, --size WxH      设备分辨率，默认 240x320（设备原生竖屏）",
32	    "  -k, --scale N       窗口放大倍数，默认 2",
33	    "  -H, --headless      不建窗口，跑固定帧数",
34	    "  -f, --frames N      headless 帧数，默认 30",
35	    "  -o, --shot PATH     headless 截图输出 PNG",
36	    "  -t, --title TEXT    窗口标题",
37	    "  -l, --list          列出所有场景",
38	    "  -h, --help          本帮助",
39	    NULL,
40	};
41	
42	static void usage(void)
43	{
44	    for (int i = 0; kUsageLines[i]; i++) {
45	        puts(kUsageLines[i]);
46	    }
47	}
48	
49	int main(int argc, char **argv)
50	{
51	    sim_cfg_t cfg;
52	    memset(&cfg, 0, sizeof(cfg));
53	    cfg.width = 240;
54	    cfg.height = 320;   /* 设备原生竖屏：状态栏 24 + 页面 296 */
55	    cfg.scale = 2;
56	    cfg.frames = 30;
57	    cfg.title = "lvgl_sim";
58	
59	    const char *scene_name = "demo";
60	    bool list_only = false;
61	
62	    static const struct option long_opts[] = {
63	        { "scene",    required_argument, 0, 's' },
64	        { "size",     required_argument, 0, 'S' },
65	        { "scale",    required_argument, 0, 'k' },
66	        { "headless", no_argument,       0, 'H' },
67	        { "frames",   required_argument, 0, 'f' },
68	        { "shot",     required_argument, 0, 'o' },
69	        { "title",    required_argument, 0, 't' },
70	        { "list",     no_argument,       0, 'l' },
71	        { "help",     no_argument,       0, 'h' },
72	        { NULL, 0, NULL, 0 },
73	    };
74	
75	    int c;
76	    while ((c = getopt_long(argc, argv, "s:S:k:Hf:o:t:lh", long_opts, NULL)) != -1) {
77	        switch (c) {
78	            case 's': scene_name = optarg; break;
79	            case 'S':
80	                if (sscanf(optarg, "%dx%d", &cfg.width, &cfg.height) != 2) {
81	                    fprintf(stderr, "bad --size\n");
82	                    return 2;
83	                }
84	                break;
85	            case 'k': cfg.scale = atoi(optarg); break;
86	            case 'H': cfg.headless = true; break;
87	            case 'f': cfg.frames = atoi(optarg); break;
88	            case 'o': cfg.shot = optarg; break;
89	            case 't': cfg.title = optarg; break;
90	            case 'l': list_only = true; break;
91	            case 'h': usage(); return 0;
92	            default: usage(); return 2;
93	        }
94	    }
95	
96	    if (list_only) {
97	        sim_scene_list();
98	        return 0;
99	    }
100	
101	    const sim_scene_t *scene = sim_scene_find(scene_name);
102	    if (!scene) {
103	        fprintf(stderr, "unknown scene\n");
104	        sim_scene_list();
105	        return 2;
106	    }
107	
108	    lv_init();
109	    lv_tick_set_cb(cfg.headless ? vtick_get : sim_tick_ms);
110	
111	    if (!sim_display_init(&cfg)) {
112	        return 1;
113	    }
114	    sim_lvgl_bind();
115	
116	    scene->create(lv_screen_active(), &cfg);
117	    printf("lvgl_sim: scene=%s %dx%d scale=%d %s\n", scene->name, cfg.width,
118	           cfg.height, cfg.scale, cfg.headless ? "headless" : "window");
119	
120	    if (cfg.headless) {
121	        for (int i = 0; i < cfg.frames; i++) {
122	            s_vtick += 16;
123	            lv_timer_handler();
124	        }
125	        if (cfg.shot) {
126	            int w = 0;
127	            int h = 0;
128	            const uint16_t *fb = sim_display_shadow(&w, &h);
129	
130	            if (!sim_png_write(cfg.shot, fb, w, h)) {
131	                fprintf(stderr, "failed to write png\n");
132	                sim_display_shutdown();
133	                return 1;
134	            }
135	            printf("shot -> %s (%dx%d)\n", cfg.shot, w, h);
136	        }
137	    } else {
138	        while (sim_display_pump()) {
139	            uint32_t idle = lv_timer_handler();
140	
141	            if (idle < 1) {
142	                idle = 1;
143	            }
144	            if (idle > 16) {
145	                idle = 16;
146	            }
147	            usleep(idle * 1000);
148	        }
149	    }
150	
151	    sim_display_shutdown();
152	    return 0;
153	}
