1	/**
2	 * @file ui_boot.c
3	 * @brief `ui` 场景：把 vendor/my_vendor 的真实 UI 启动起来。
4	 *
5	 * 这个函数**照抄** `ui/bicycle/src/bicycle_c_main.c` 的 `main()`，只做两处替换：
6	 *   1. 板级 LCD / `lv_nuttx_init()` 那几步去掉 —— display 已经由模拟器的
7	 *      `sim_lvgl_bind()` 建好（X11 窗口或 headless 影子缓冲），这里用
8	 *      `lv_display_get_default()` 拿同一个句柄；
9	 *   2. `lv_init()` 不调（`src/main.c` 已经调过）。
10	 *
11	 * 剩下的顺序与板端一致：黑屏/停刷新 → 注册 flush done 回调（板级，略）→
12	 * `lvgl_page_init()` → `open_boot_sequence()` → `sync_boot()` → 开刷新 →
13	 * `bicycle_mtp_ui_init()` → `lvgl_page_set_app_started(true)` → `ui_ctl_ready()`。
14	 *
15	 * 板端 `while (1)` 里的每拍工作（ctl 队列、传感器同步、演示模式、主题换装）
16	 * 由 `ui_tick_cb` 这个 10 ms 的 LVGL 定时器承担 —— 它就在 `lv_timer_handler()`
17	 * 里跑，等价于板端"循环顶 + 帧后"两段逻辑的合并版。
18	 */
19	
20	#include <stdio.h>
21	#include <sys/stat.h>
22	#include <unistd.h>
23	
24	#include "sim.h"
25	#include "sim_config.h"
26	
27	#include "lvgl_page.h"
28	#include "bicycle_demo.h"
29	#include "bicycle_mtp_ui.h"
30	#include "bicycle_runtime.h"
31	#include "bicycle_ui_ctl.h"
32	#include "helm_palette.h"
33	#include "live_map/map_page.h"
34	#include "lv_pm_theme.h"
35	#include "myvendor_identity.h"
36	#include "startup/startup_page.h"
37	#include "Vendor/Board/lv_port/lv_port_buttons.h"
38	
39	/** 板端 `BICYCLE_LOOP_SLEEP_MS`：主循环 10 ms 一拍。 */
40	#define SIM_UI_TICK_MS 10u
41	
42	static bool s_started;
43	static bicycle_mtp_ui_t s_mtp_ui;
44	
45	/**
46	 * @brief 板端 while(1) 的主体（去掉 usleep 与 watchdog/性能探针）。
47	 *
48	 * 顺序照抄 `bicycle_c_main.c`：ctl 队列 → 传感器 → 演示 →（帧后）主题重活。
49	 */
50	static void sim_ui_loop_body(void)
51	{
52	    map_page_t *page = lvgl_page_map();
53	
54	    bicycle_mtp_ui_run(&s_mtp_ui);
55	    bicycle_ui_ctl_poll(page);
56	    bicycle_runtime_sync_companion_sensors();
57	    bicycle_demo_poll();
58	
59	    /* 这两步在板端放在 lv_timer_handler() 之后（帧后做换主题的重活），
60	     * 在定时器回调里已经是"帧内"，顺序等价。 */
61	    helm_theme_poll_apply();
62	    lv_pm_theme_poll_styles();
63	
64	    if (page && !lvgl_page_is_usb_transfer()) {
65	        map_page_debug_snap(page);
66	    }
67	}
68	
69	static void ui_tick_cb(lv_timer_t *tmr)
70	{
71	    (void)tmr;
72	    sim_ui_loop_body();
73	}
74	
75	/* 板端 `vmap_map_catalog.c` 把地图目录存进 **64 字节** 的 `char map_dir[64]`，
76	 * PC 上那条 mkfs 绝对路径（90+ 字符）会被截断 ⇒ 找不到瓦片、地图空白。
77	 * 所以给一个短路径，指向设备真正烧的那份网格包。 */
78	static void ensure_short_map_path(void)
79	{
80	    const char *short_path = "/tmp/vmap";
81	    struct stat st;
82	
83	    if (lstat(short_path, &st) == 0) {
84	        return;
85	    }
86	    if (symlink(SIM_VMAP_REAL_DIR, short_path) != 0) {
87	        fprintf(stderr, "sim_ui: 建不了 %s -> %s（地图会空白）\n",
88	                short_path, SIM_VMAP_REAL_DIR);
89	    }
90	}
91	
92	void sim_ui_start(void)
93	{
94	    lv_display_t *disp;
95	    lv_obj_t *scr;
96	    lv_timer_t *refr;
97	    map_page_t *page;
98	    int rc;
99	
100	    if (s_started) {
101	        return;
102	    }
103	    s_started = true;
104	
105	    ensure_short_map_path();
106	
107	    disp = lv_display_get_default();
108	    if (disp == NULL) {
109	        fprintf(stderr, "sim_ui: no display (sim_lvgl_bind 没跑？)\n");
110	        return;
111	    }
112	
113	    printf("sim_ui: boot start %dx%d\n", (int)lv_display_get_horizontal_resolution(disp),
114	           (int)lv_display_get_vertical_resolution(disp));
115	
116	    /* ── 与 bicycle_c_main.c 完全一致的前奏 ────────────────────────────── */
117	    scr = lv_display_get_screen_active(disp);
118	    lv_obj_set_style_bg_color(scr, lv_color_black(), 0);
119	    lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);
120	    /* 开机时先不让 LVGL 刷：板端是为了把 2SFBL 的像素留在屏上。 */
121	    lv_display_enable_invalidation(disp, false);
122	    refr = lv_display_get_refr_timer(disp);
123	    if (refr) {
124	        lv_timer_pause(refr);
125	    }
126	
127	    lv_display_set_antialiasing(disp, true);
128	
129	    /* CONFIG_MYVENDOR_LCD_DISP 的 flush done 回调是板级 /dev/lcd0 的东西，模拟器
130	     * 的 flush_cb 自己调 lv_display_flush_ready()，不需要也不该再注册。 */
131	
132	    /* 按键：PC 上 lv_port_buttons.c 整份被 `#if defined(__NuttX__)` 关掉，
133	     * 这里调用的是它自己的空实现，与板端保持同一调用点。 */
134	    lv_port_buttons_init();
135	
136	    lvgl_page_init();
137	
138	    rc = lvgl_page_open_boot_sequence();
139	    if (rc != 0) {
140	        fprintf(stderr, "sim_ui: lvgl_page_open_boot_sequence failed (%d)\n", rc);
141	        return;
142	    }
143	
144	    if (!myvendor_is_factory()) {
145	        startup_page_sync_boot();
146	    }
147	
148	    printf("sim_ui: pages registered, splash open\n");
149	
150	    /* splash / 工厂页用编译进去的 helm 点阵字体，先画一帧再谈 TTF / MTP / vmap */
151	    lv_display_enable_invalidation(disp, true);
152	    refr = lv_display_get_refr_timer(disp);
153	    if (refr) {
154	        lv_timer_resume(refr);
155	    }
156	    scr = lv_display_get_screen_active(disp);
157	    lv_obj_invalidate(scr);
158	    lv_obj_update_layout(scr);
159	    lv_refr_now(disp);
160	
161	    page = lvgl_page_map();
162	    if (!page) {
163	        printf("sim_ui: splash active, LiveMap loads under Startup\n");
164	    }
165	
166	    /* MTP：模拟器没有 USB 端点，不启 worker（myvendor_mtp_init 是板级线程），
167	     * 只初始化 UI 侧状态机，让页面切换逻辑照常跑。 */
168	    bicycle_mtp_ui_init(&s_mtp_ui);
169	
170	    lvgl_page_set_app_started(true);
171	
172	    printf("sim_ui: app started, ui_ctl ready\n");
173	    bicycle_ui_ctl_ready();
174	    bicycle_ui_ctl_sync_state();
175	
176	    /* 板端 while(1) 的等价物 */
177	    lv_timer_create(ui_tick_cb, SIM_UI_TICK_MS, NULL);
178	
179	    printf("sim_ui: boot done (10 ms tick running)\n");
180	}
