1	/**
2	 * @file sim_display.c
3	 * @brief X11 窗口 + LVGL display/indev 绑定；headless 下只维护影子帧缓冲。
4	 *
5	 * 为什么不照搬 lv_port_linux：那个工程是 Kconfig/CMake 组件化的，源文件
6	 * 依赖它的 SDK 框架。这里只要"一块 RGB565 画布 + 鼠标键盘"，自己写
7	 * 200 行比拖一整套框架干净，而且窗口缩放、headless 截图都能自己控制。
8	 */
9	
10	#define _POSIX_C_SOURCE 199309L
11	
12	#include <stdio.h>
13	#include <stdlib.h>
14	#include <string.h>
15	#include <time.h>
16	
17	#include <X11/Xlib.h>
18	#include <X11/Xutil.h>
19	#include <X11/keysym.h>
20	
21	#include "sim.h"
22	
23	static struct {
24	    Display *dpy;
25	    Window win;
26	    GC gc;
27	    XImage *img;
28	    Atom wm_delete;
29	    int w, h, scale;
30	    bool headless;
31	    bool quit;
32	
33	    int mx, my;
34	    bool pressed;
35	
36	    lv_group_t *group;
37	    lv_indev_t *indev_ptr;
38	    lv_indev_t *indev_key;
39	
40	    uint32_t keys[32];
41	    int key_head, key_tail;
42	    uint32_t last_key;
43	
44	    uint16_t *shadow;   /* 整帧影子：Expose 重画 + headless 截图都靠它 */
45	} s;
46	
47	uint32_t sim_tick_ms(void)
48	{
49	    struct timespec ts;
50	
51	    clock_gettime(CLOCK_MONOTONIC, &ts);
52	    return (uint32_t)((uint64_t)ts.tv_sec * 1000u + (uint64_t)ts.tv_nsec / 1000000u);
53	}
54	
55	static inline uint32_t rgb565_to_xrgb(uint16_t c)
56	{
57	    uint32_t r = (uint32_t)((c >> 11) & 0x1Fu);
58	    uint32_t g = (uint32_t)((c >> 5) & 0x3Fu);
59	    uint32_t b = (uint32_t)(c & 0x1Fu);
60	
61	    r = (r << 3) | (r >> 2);
62	    g = (g << 2) | (g >> 4);
63	    b = (b << 3) | (b >> 2);
64	    return (r << 16) | (g << 8) | b;
65	}
66	
67	/* 把影子缓冲的一块画到窗口（只画脏矩形，缩放用最近邻）。 */
68	static void blit_rect(int x0, int y0, int w, int h)
69	{
70	    if (s.headless || !s.dpy || !s.img) {
71	        return;
72	    }
73	
74	    const int sc = s.scale;
75	    const int iw = s.w * sc;
76	    const bool fast = (s.img->bits_per_pixel == 32);
77	
78	    for (int y = 0; y < h; y++) {
79	        const uint16_t *src = s.shadow + (size_t)(y0 + y) * (size_t)s.w + x0;
80	        for (int sy = 0; sy < sc; sy++) {
81	            int row = (y0 + y) * sc + sy;
82	            for (int x = 0; x < w; x++) {
83	                uint32_t rgb = rgb565_to_xrgb(src[x]);
84	                for (int sx = 0; sx < sc; sx++) {
85	                    int col = (x0 + x) * sc + sx;
86	                    if (fast) {
87	                        ((uint32_t *)s.img->data)[(size_t)row * (size_t)iw + col] = rgb;
88	                    } else {
89	                        XPutPixel(s.img, col, row, rgb);
90	                    }
91	                }
92	            }
93	        }
94	    }
95	    XPutImage(s.dpy, s.win, s.gc, s.img, x0 * sc, y0 * sc, x0 * sc, y0 * sc,
96	              (unsigned)w * (unsigned)sc, (unsigned)h * (unsigned)sc);
97	    XFlush(s.dpy);
98	}
99	
100	/* ── LVGL flush ────────────────────────────────────────────────── */
101	
102	static void flush_cb(lv_display_t *disp, const lv_area_t *area, uint8_t *px_map)
103	{
104	    const int w = (int)lv_area_get_width(area);
105	    const int h = (int)lv_area_get_height(area);
106	    const uint16_t *px = (const uint16_t *)px_map;
107	
108	    for (int y = 0; y < h; y++) {
109	        memcpy(s.shadow + (size_t)(area->y1 + y) * (size_t)s.w + area->x1,
110	               px + (size_t)y * (size_t)w, (size_t)w * 2u);
111	    }
112	    blit_rect(area->x1, area->y1, w, h);
113	    lv_display_flush_ready(disp);
114	}
115	
116	/* ── 输入 ──────────────────────────────────────────────────────── */
117	
118	static void pointer_read(lv_indev_t *indev, lv_indev_data_t *data)
119	{
120	    (void)indev;
121	    data->point.x = (int32_t)s.mx;
122	    data->point.y = (int32_t)s.my;
123	    data->state = s.pressed ? LV_INDEV_STATE_PRESSED : LV_INDEV_STATE_RELEASED;
124	}
125	
126	static void key_push(uint32_t key)
127	{
128	    int next = (s.key_tail + 1) % (int)(sizeof(s.keys) / sizeof(s.keys[0]));
129	
130	    if (next == s.key_head) {
131	        return;
132	    }
133	    s.keys[s.key_tail] = key;
134	    s.key_tail = next;
135	}
136	
137	static void keypad_read(lv_indev_t *indev, lv_indev_data_t *data)
138	{
139	    (void)indev;
140	    if (s.key_head != s.key_tail) {
141	        s.last_key = s.keys[s.key_head];
142	        s.key_head = (s.key_head + 1) % (int)(sizeof(s.keys) / sizeof(s.keys[0]));
143	        data->state = LV_INDEV_STATE_PRESSED;
144	    } else {
145	        data->state = LV_INDEV_STATE_RELEASED;
146	    }
147	    data->key = s.last_key;
148	}
149	
150	static uint32_t xkey_to_lv(KeySym ks)
151	{
152	    switch (ks) {
153	        case XK_Left:  return LV_KEY_LEFT;
154	        case XK_Right: return LV_KEY_RIGHT;
155	        case XK_Up:    return LV_KEY_UP;
156	        case XK_Down:  return LV_KEY_DOWN;
157	        case XK_Return:
158	        case XK_KP_Enter: return LV_KEY_ENTER;
159	        case XK_Escape:   return LV_KEY_ESC;
160	        case XK_BackSpace:return LV_KEY_BACKSPACE;
161	        case XK_Tab:      return LV_KEY_NEXT;
162	        case XK_Home:     return LV_KEY_HOME;
163	        case XK_End:      return LV_KEY_END;
164	        default: return 0;
165	    }
166	}
167	
168	lv_group_t *sim_input_group(void)
169	{
170	    if (!s.group) {
171	        s.group = lv_group_create();
172	        lv_group_set_default(s.group);
173	    }
174	    return s.group;
175	}
176	
177	/* ── 事件循环 ──────────────────────────────────────────────────── */
178	
179	bool sim_display_pump(void)
180	{
181	    if (s.headless || !s.dpy) {
182	        return !s.quit;
183	    }
184	
185	    while (XPending(s.dpy)) {
186	        XEvent ev;
187	
188	        XNextEvent(s.dpy, &ev);
189	        switch (ev.type) {
190	            case Expose:
191	                if (ev.xexpose.count == 0) {
192	                    blit_rect(0, 0, s.w, s.h);
193	                }
194	                break;
195	            case MotionNotify:
196	                s.mx = ev.xmotion.x / s.scale;
197	                s.my = ev.xmotion.y / s.scale;
198	                if (s.mx < 0) s.mx = 0;
199	                if (s.my < 0) s.my = 0;
200	                if (s.mx > s.w - 1) s.mx = s.w - 1;
201	                if (s.my > s.h - 1) s.my = s.h - 1;
202	                break;
203	            case ButtonPress:
204	                if (ev.xbutton.button == Button1) {
205	                    s.pressed = true;
206	                }
207	                break;
208	            case ButtonRelease:
209	                if (ev.xbutton.button == Button1) {
210	                    s.pressed = false;
211	                }
212	                break;
213	            case KeyPress: {
214	                KeySym ks = XLookupKeysym(&ev.xkey, 0);
215	                uint32_t key = xkey_to_lv(ks);
216	
217	                if (key) {
218	                    key_push(key);
219	                }
220	                break;
221	            }
222	            case ClientMessage:
223	                if ((Atom)ev.xclient.data.l[0] == s.wm_delete) {
224	                    s.quit = true;
225	                }
226	                break;
227	            case DestroyNotify:
228	                s.quit = true;
229	                break;
230	            default:
231	                break;
232	        }
233	    }
234	    return !s.quit;
235	}
236	
237	/* ── 初始化 ────────────────────────────────────────────────────── */
238	
239	static bool shadow_alloc(void)
240	{
241	    s.shadow = calloc((size_t)s.w * (size_t)s.h, sizeof(uint16_t));
242	    if (!s.shadow) {
243	        fprintf(stderr, "sim: out of memory for shadow framebuffer\n");
244	        return false;
245	    }
246	    for (size_t i = 0; i < (size_t)s.w * (size_t)s.h; i++) {
247	        s.shadow[i] = 0xFFFF;
248	    }
249	    return true;
250	}
251	
252	static bool window_open(const sim_cfg_t *cfg)
253	{
254	    const int scr = DefaultScreen(s.dpy);
255	    const int win_w = s.w * s.scale;
256	    const int win_h = s.h * s.scale;
257	
258	    s.win = XCreateSimpleWindow(s.dpy, RootWindow(s.dpy, scr), 0, 0,
259	                                (unsigned)win_w, (unsigned)win_h, 0,
260	                                BlackPixel(s.dpy, scr), WhitePixel(s.dpy, scr));
261	    XStoreName(s.dpy, s.win, cfg->title ? cfg->title : "lvgl_sim");
262	
263	    XSizeHints hints;
264	    memset(&hints, 0, sizeof(hints));
265	    hints.flags = PMinSize | PMaxSize;
266	    hints.min_width = hints.max_width = win_w;
267	    hints.min_height = hints.max_height = win_h;
268	    XSetWMNormalHints(s.dpy, s.win, &hints);
269	
270	    s.wm_delete = XInternAtom(s.dpy, "WM_DELETE_WINDOW", False);
271	    XSetWMProtocols(s.dpy, s.win, &s.wm_delete, 1);
272	
273	    XSelectInput(s.dpy, s.win,
274	                 ExposureMask | ButtonPressMask | ButtonReleaseMask |
275	                 PointerMotionMask | KeyPressMask | StructureNotifyMask);
276	
277	    s.gc = XCreateGC(s.dpy, s.win, 0, NULL);
278	
279	    s.img = XCreateImage(s.dpy, DefaultVisual(s.dpy, scr),
280	                         (unsigned)DefaultDepth(s.dpy, scr), ZPixmap, 0, NULL,
281	                         (unsigned)win_w, (unsigned)win_h, 32, 0);
282	    if (!s.img) {
283	        fprintf(stderr, "sim: XCreateImage failed\n");
284	        return false;
285	    }
286	    s.img->data = calloc((size_t)s.img->bytes_per_line, (size_t)win_h);
287	    if (!s.img->data) {
288	        fprintf(stderr, "sim: out of memory for XImage\n");
289	        return false;
290	    }
291	
292	    XMapWindow(s.dpy, s.win);
293	    XFlush(s.dpy);
294	
295	    if (s.img->bits_per_pixel != 32) {
296	        fprintf(stderr, "sim: warning: X server is %d bpp, using slow XPutPixel path\n",
297	                s.img->bits_per_pixel);
298	    }
299	    return true;
300	}
301	
302	bool sim_display_init(const sim_cfg_t *cfg)
303	{
304	    s.w = cfg->width > 0 ? cfg->width : 240;
305	    s.h = cfg->height > 0 ? cfg->height : 400;
306	    s.scale = cfg->scale > 0 ? cfg->scale : 2;
307	    s.headless = cfg->headless;
308	    s.quit = false;
309	
310	    if (!shadow_alloc()) {
311	        return false;
312	    }
313	    if (s.headless) {
314	        return true;
315	    }
316	
317	    s.dpy = XOpenDisplay(NULL);
318	    if (!s.dpy) {
319	        fprintf(stderr, "sim: cannot open X display; use --headless --shot out.png\n");
320	        return false;
321	    }
322	    return window_open(cfg);
323	}
324	
325	void sim_lvgl_bind(void)
326	{
327	    /* 两个 1/10 屏的局部缓冲：和设备的渲染模式一致，刷新时只送脏矩形 */
328	    const uint32_t stride = (uint32_t)s.w;
329	    const uint32_t lines = 40;
330	    const uint32_t bytes = stride * lines * 2u;
331	    void *buf1 = lv_malloc(bytes);
332	    void *buf2 = lv_malloc(bytes);
333	
334	    lv_display_t *disp = lv_display_create(s.w, s.h);
335	
336	    lv_display_set_flush_cb(disp, flush_cb);
337	    lv_display_set_buffers(disp, buf1, buf2, bytes, LV_DISPLAY_RENDER_MODE_PARTIAL);
338	    lv_display_set_default(disp);
339	
340	    s.indev_ptr = lv_indev_create();
341	    lv_indev_set_type(s.indev_ptr, LV_INDEV_TYPE_POINTER);
342	    lv_indev_set_read_cb(s.indev_ptr, pointer_read);
343	
344	    s.indev_key = lv_indev_create();
345	    lv_indev_set_type(s.indev_key, LV_INDEV_TYPE_KEYPAD);
346	    lv_indev_set_read_cb(s.indev_key, keypad_read);
347	    lv_indev_set_group(s.indev_key, sim_input_group());
348	}
349	
350	const uint16_t *sim_display_shadow(int *w, int *h)
351	{
352	    if (w) *w = s.w;
353	    if (h) *h = s.h;
354	    return s.shadow;
355	}
356	
357	void sim_display_shutdown(void)
358	{
359	    if (s.img) {
360	        /* XDestroyImage 会 free(data) */
361	        XDestroyImage(s.img);
362	        s.img = NULL;
363	    }
364	    if (s.gc && s.dpy) {
365	        XFreeGC(s.dpy, s.gc);
366	        s.gc = NULL;
367	    }
368	    if (s.win && s.dpy) {
369	        XDestroyWindow(s.dpy, s.win);
370	        s.win = 0;
371	    }
372	    if (s.dpy) {
373	        XCloseDisplay(s.dpy);
374	        s.dpy = NULL;
375	    }
376	    free(s.shadow);
377	    s.shadow = NULL;
378	}
