1	/**
2	 * @file sim_png.c
3	 * @brief RGB565 帧缓冲 → PNG（headless 截图用）。
4	 */
5	
6	#include <png.h>
7	#include <setjmp.h>
8	#include <stdio.h>
9	#include <stdlib.h>
10	
11	#include "sim.h"
12	
13	bool sim_png_write(const char *path, const uint16_t *fb, int w, int h)
14	{
15	    if (!path || !fb || w <= 0 || h <= 0) {
16	        return false;
17	    }
18	
19	    FILE *fp = fopen(path, "wb");
20	    if (!fp) {
21	        perror(path);
22	        return false;
23	    }
24	
25	    png_structp png = png_create_write_struct(PNG_LIBPNG_VER_STRING, NULL, NULL, NULL);
26	    if (!png) {
27	        fclose(fp);
28	        return false;
29	    }
30	    png_infop info = png_create_info_struct(png);
31	    if (!info) {
32	        png_destroy_write_struct(&png, NULL);
33	        fclose(fp);
34	        return false;
35	    }
36	
37	    uint8_t *row = NULL;
38	    if (setjmp(png_jmpbuf(png))) {
39	        free(row);
40	        png_destroy_write_struct(&png, &info);
41	        fclose(fp);
42	        return false;
43	    }
44	
45	    png_init_io(png, fp);
46	    png_set_IHDR(png, info, (png_uint_32)w, (png_uint_32)h, 8,
47	                 PNG_COLOR_TYPE_RGB, PNG_INTERLACE_NONE,
48	                 PNG_COMPRESSION_TYPE_DEFAULT, PNG_FILTER_TYPE_DEFAULT);
49	    png_write_info(png, info);
50	
51	    row = malloc((size_t)w * 3u);
52	    if (!row) {
53	        png_destroy_write_struct(&png, &info);
54	        fclose(fp);
55	        return false;
56	    }
57	
58	    for (int y = 0; y < h; y++) {
59	        const uint16_t *src = fb + (size_t)y * (size_t)w;
60	        for (int x = 0; x < w; x++) {
61	            const uint16_t c = src[x];
62	            const uint32_t r5 = (uint32_t)((c >> 11) & 0x1Fu);
63	            const uint32_t g6 = (uint32_t)((c >> 5) & 0x3Fu);
64	            const uint32_t b5 = (uint32_t)(c & 0x1Fu);
65	
66	            row[x * 3 + 0] = (uint8_t)((r5 << 3) | (r5 >> 2));
67	            row[x * 3 + 1] = (uint8_t)((g6 << 2) | (g6 >> 4));
68	            row[x * 3 + 2] = (uint8_t)((b5 << 3) | (b5 >> 2));
69	        }
70	        png_write_row(png, row);
71	    }
72	
73	    png_write_end(png, NULL);
74	    free(row);
75	    png_destroy_write_struct(&png, &info);
76	    fclose(fp);
77	    return true;
78	}
