static void startup_on_unload(void * pm_page)
{
    lv_pm_page_t page = lv_pm_get_pm_page(pm_page);
    startup_page_t * ui;

    if (!page) {
        return;
    }

    ui = (startup_page_t *)page->user_data;
    if (!ui) {
        return;
    }

    startup_stop_bg_anim(ui);
    if (ui->poll_timer) {
        lv_timer_del(ui->poll_timer);
        ui->poll_timer = NULL;
    }

    helm_splash_clear(&ui->splash);
    lv_pm_free(ui);
    page->user_data = NULL;
    s_startup = NULL;
}

