{"file_path": "/home/jinsc/SDK/vela/lvgl_sim/ui_port/ui_tour.c", "content": "/**
 * @file ui_tour.c
 * @brief `ui` 场景巡页（模拟器专用）：开机 → 逐页截图 → 逐主题截图。
 *
 * 只在命令行给了 `--ui-tour DIR` 时启用（见 `src/main.c` / `src/scenes.c`）：
 * 不给时本文件什么都不做，现有 demo / vmap / 普通 ui 场景行为不变。
 *
 * 设计约束（WP-UI3 / R1）：
 *   - 状态机跑在 LVGL timer 里（10 ms 一拍），**不阻塞**主循环；
 *   - 截图复用 `sim_display_shadow()` + `sim_png_write()`（headless 下影子缓冲
 *     就是整帧）；
 *   - 不动板端 UI 代码，只用公开入口 `lv_pm_open_page_msg()` /
 *     `lv_pm_close_page_msg()` / `lvgl_page_theme_set_by_name()`。
 *
 * 页面顺序：MAP → MENU → STARTUP（splash）→ USB_TRANSFER；FACTORY 需要
 * CONFIG_MYVENDOR_FACTORY_MODE，模拟器未开，跳过并在日志里注明。
 */

#include <errno.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>

#include "sim.h"
#include "sim_config.h"

#include "bicycle_page_ids.h"
#include "lvgl_page.h"
#include "lv_pm_core.h"

/** 巡页定时器周期：与板端主循环同拍（10 ms）。headless 下每个 host 帧
 *  推进 16 ms 虚拟时间，所以每帧恰好触发一次。 */
#define TOUR_TIMER_MS 10u
/** splash 等不到结束时放弃等待的拍数上限（约 32 s 虚拟时间）。 */
#define TOUR_BOOT_TIMEOUT 2000
/** 转场动画卡住时强制 drain 的拍数上限。 */
#define TOUR_NAV_TIMEOUT 500

typedef enum {
    TOUR_ST_BOOT = 0,   /**< 等开机 splash 结束、LiveMap 露出。 */
    TOUR_ST_OPEN,       /**< arg=页面 ID：打开页面（已打开则跳过）。 */
    TOUR_ST_CLOSE,      /**< arg=页面 ID：当前是它就 close，否则跳过。 */
    TOUR_ST_THEME,      /**< name=主题名。 */
    TOUR_ST_SETTLE,     /**< 等转场结束，再等 frames 拍。 */
    TOUR_ST_SHOT,       /**< name=输出文件名（不带 .png）。 */
    TOUR_ST_DONE,       /**< 结束。 */
} tour_kind_t;

typedef struct {
    tour_kind_t kind;
    int arg;
    const char *name;
} tour_step_t;

/**
 * @brief 巡页剧本。
 *
 * 主题三档按 classic / outdoor / night 各截一张，最后恢复 classic。
 * STARTUP 重新打开会再播一遍 splash；截图在 appear 后 frames 拍，正常参数
 * （--tour-frames 90 ≈ 1.4 s）落在事项滚动中间。
 */
static const tour_step_t kSteps[] = {
    { TOUR_ST_BOOT,   0,                          NULL },
    { TOUR_ST_SETTLE, 0,                          NULL },
    { TOUR_ST_SHOT,   0,                          "page_map" },

    { TOUR_ST_THEME,  0,                          "classic" },
    { TOUR_ST_SETTLE, 0,                          NULL },
    { TOUR_ST_SHOT,   0,                          "theme_classic" },
    { TOUR_ST_THEME,  0,                          "outdoor" },
    { TOUR_ST_SETTLE, 0,                          NULL },
    { TOUR_ST_SHOT,   0,                          "theme_outdoor" },
    { TOUR_ST_THEME,  0,                          "night" },
    { TOUR_ST_SETTLE, 0,                          NULL },
    { TOUR_ST_SHOT,   0,                          "theme_night" },
    { TOUR_ST_THEME,  0,                          "classic" },
    { TOUR_ST_SETTLE, 0,                          NULL },

    { TOUR_ST_OPEN,   BICYCLE_PM_ID_MENU,         NULL },
    { TOUR_ST_SETTLE, 0,                          NULL },
    { TOUR_ST_SHOT,   0,                          "page_menu" },
    { TOUR_ST_CLOSE,  BICYCLE_PM_ID_MENU,         NULL },

    { TOUR_ST_OPEN,   BICYCLE_PM_ID_STARTUP,      NULL },
    { TOUR_ST_SETTLE, 0,                          NULL },
    { TOUR_ST_SHOT,   0,                          "page_startup" },
    { TOUR_ST_CLOSE,  BICYCLE_PM_ID_STARTUP,      NULL },

    { TOUR_ST_OPEN,   BICYCLE_PM_ID_USB_TRANSFER, NULL },
    { TOUR_ST_SETTLE, 0,                          NULL },
    { TOUR_ST_SHOT,   0,                          "page_usb_transfer" },

    { TOUR_ST_DONE,   0,                          NULL },
};

#define TOUR_STEP_COUNT ((int)(sizeof(kSteps) / sizeof(kSteps[0])))

static struct {
    bool configured;
    bool started;
    bool done;
    bool failed;
    char dir[480];
    int frames;
    int step;
    int waited;
    int nav_wait;
    int boot_wait;
    lv_timer_t *tmr;
} s_tour;

static const char *tour_page_name(int id)
{
    switch (id) {
        case BICYCLE_PM_ID_MAP:          return "map";
        case BICYCLE_PM_ID_USB_TRANSFER: return "usb_transfer";
        case BICYCLE_PM_ID_STARTUP:      return "startup";
        case BICYCLE_PM_ID_MENU:         return "menu";
        case BICYCLE_PM_ID_FACTORY:      return "factory";
        default:                         return "?";
    }
}

static void tour_log(const char *fmt, ...)
{
    va_list ap;

    fputs("[tour] ", stdout);
    va_start(ap, fmt);
    vprintf(fmt, ap);
    va_end(ap);
    fputc('\n', stdout);
    fflush(stdout);
}

/** `mkdir -p`：逐级建目录（已存在不算错）。 */
static bool tour_mkdir_p(const char *dir)
{
    char tmp[sizeof(s_tour.dir)];
    size_t len = strlen(dir);

    if (len == 0 || len >= sizeof(tmp)) {
        return false;
    }
    memcpy(tmp, dir, len + 1);

    for (char *p = tmp + 1; *p; p++) {
        if (*p != '/') {
            continue;
        }
        *p = '\0';
        if (mkdir(tmp, 0777) != 0 && errno != EEXIST) {
            return false;
        }
        *p = '/';
    }
    if (mkdir(tmp, 0777) != 0 && errno != EEXIST) {
        return false;
    }
    return true;
}

/** 整屏失效后同步刷一遍，把影子缓冲补成完整一帧，再写 PNG。 */
static void tour_take_shot(const char *name)
{
    char path[sizeof(s_tour.dir) + 64];
    const uint16_t *fb;
    int w = 0;
    int h = 0;

    lv_obj_invalidate(lv_screen_active());
    lv_refr_now(NULL);

    fb = sim_display_shadow(&w, &h);
    if (snprintf(path, sizeof(path), "%s/%s.png", s_tour.dir, name) >= (int)sizeof(path)) {
        fprintf(stderr, "[tour] path too long: %s/%s.png\n", s_tour.dir, name);
        s_tour.failed = true;
        return;
    }

    if (sim_png_write(path, fb, w, h)) {
        tour_log("shot %s (%dx%d)", path, w, h);
    } else {
        fprintf(stderr, "[tour] shot FAILED %s\n", path);
        s_tour.failed = true;
    }
}

/** 开机结束的判据：splash 已 pop、无转场在跑、LiveMap 实例已建。 */
static bool tour_boot_ready(void)
{
    bicycle_pm_id_t id = lvgl_page_current_id();

    if (lv_pm_nav_busy()) {
        return false;
    }
    if (id == BICYCLE_PM_ID_STARTUP) {
        return false;
    }
    return lvgl_page_map() != NULL;
}

static void tour_next_step(void)
{
    s_tour.step++;
    s_tour.waited = 0;
    s_tour.nav_wait = 0;
}

static void tour_finish(void)
{
    s_tour.done = true;
    if (s_tour.tmr) {
        lv_timer_delete(s_tour.tmr);
        s_tour.tmr = NULL;
    }
    tour_log("%s (dir=%s, frames=%d)", s_tour.failed ? "done WITH ERRORS" : "done",
             s_tour.dir, s_tour.frames);
    tour_log("note: page_factory skipped (CONFIG_MYVENDOR_FACTORY_MODE off in sim)");
}

static void tour_tick_cb(lv_timer_t *tmr)
{
    (void)tmr;

    if (!s_tour.started || s_tour.done || s_tour.failed) {
        return;
    }
    if (s_tour.step < 0 || s_tour.step >= TOUR_STEP_COUNT) {
        tour_finish();
        return;
    }

    const tour_step_t *st = &kSteps[s_tour.step];

    switch (st->kind) {
        case TOUR_ST_BOOT:
            s_tour.boot_wait++;
            if (tour_boot_ready()) {
                tour_log("boot: splash finished, page=%s, waited %d ticks (%u ms virtual)",
                         tour_page_name((int)lvgl_page_current_id()),
                         s_tour.boot_wait, (unsigned)s_tour.boot_wait * TOUR_TIMER_MS);
                tour_next_step();
            } else if (s_tour.boot_wait >= TOUR_BOOT_TIMEOUT) {
                tour_log("boot: timeout after %d ticks, current page=%s (continue)",
                         s_tour.boot_wait,
                         tour_page_name((int)lvgl_page_current_id()));
                tour_next_step();
            }
            return;

        case TOUR_ST_OPEN: {
            bicycle_pm_id_t cur = lvgl_page_current_id();

            if ((int)cur == st->arg) {
                tour_log("open %s: already current, skip", tour_page_name(st->arg));
            } else {
                int rc = lv_pm_open_page_msg((lv_pm_id)st->arg, LV_PM_MSG_NONE);

                if (rc == 0) {
                    tour_log("open %s: ok", tour_page_name(st->arg));
                } else {
                    tour_log("open %s: FAILED rc=%d", tour_page_name(st->arg), rc);
                    s_tour.failed = true;
                    return;
                }
            }
            tour_next_step();
            return;
        }

        case TOUR_ST_CLOSE: {
            bicycle_pm_id_t cur = lvgl_page_current_id();

            if ((int)cur != st->arg) {
                tour_log("close %s: not current (now %s), skip",
                         tour_page_name(st->arg), tour_page_name((int)cur));
            } else {
                int rc = lv_pm_close_page_msg(LV_PM_MSG_NONE);

                if (rc == 0) {
                    tour_log("close %s: ok", tour_page_name(st->arg));
                } else {
                    tour_log("close %s: FAILED rc=%d", tour_page_name(st->arg), rc);
                    s_tour.failed = true;
                    return;
                }
            }
            tour_next_step();
            return;
        }

        case TOUR_ST_THEME:
            if (lvgl_page_theme_set_by_name(st->name)) {
                tour_log("theme -> %s (now %s)", st->name, lvgl_page_theme_name());
            } else {
                tour_log("theme -> %s: FAILED (now %s)", st->name,
                         lvgl_page_theme_name());
                s_tour.failed = true;
                return;
            }
            tour_next_step();
            return;

        case TOUR_ST_SETTLE:
            /* 转场动画没完先等它；卡死就 drain（与板端抢占策略一致）。 */
            if (lv_pm_nav_busy()) {
                s_tour.nav_wait++;
                if (s_tour.nav_wait >= TOUR_NAV_TIMEOUT) {
                    tour_log("settle: nav busy %d ticks, drain", s_tour.nav_wait);
                    lv_pm_nav_drain();
                    s_tour.nav_wait = 0;
                    s_tour.waited = 0;
                }
                return;
            }

            if (s_tour.waited < s_tour.frames) {
                s_tour.waited++;
                return;
            }
            tour_next_step();
            return;

        case TOUR_ST_SHOT:
            tour_take_shot(st->name);
            tour_next_step();
            return;

        case TOUR_ST_DONE:
        default:
            tour_finish();
            return;
    }
}

/**
 * @brief 记录巡页参数（`--ui-tour` / `--tour-frames`）。
 * @note 必须在 `sim_ui_start()` 之前调用（见 `src/scenes.c`）。
 */
void sim_ui_tour_configure(const char *dir, int frames)
{
    s_tour.configured = false;
    if (dir == NULL || dir[0] == '\0') {
        return;
    }
    if (strlen(dir) >= sizeof(s_tour.dir)) {
        fprintf(stderr, "[tour] dir too long, disabled: %s\n", dir);
        return;
    }
    strcpy(s_tour.dir, dir);
    s_tour.frames = (frames > 0) ? frames : 90;
    s_tour.configured = true;
}

/**
 * @brief 开机序列跑完后启动巡页（由 ui_boot.c 在末尾调用）。
 */
void sim_ui_tour_start(void)
{
    if (!s_tour.configured || s_tour.started) {
        return;
    }
    s_tour.started = true;

    if (!tour_mkdir_p(s_tour.dir)) {
        fprintf(stderr, "[tour] cannot create dir %s: %s\n", s_tour.dir,
                strerror(errno));
        s_tour.failed = true;
        return;
    }

    tour_log("start dir=%s frames=%d steps=%d", s_tour.dir, s_tour.frames,
             TOUR_STEP_COUNT);
    s_tour.tmr = lv_timer_create(tour_tick_cb, TOUR_TIMER_MS, NULL);
    if (!s_tour.tmr) {
        fprintf(stderr, "[tour] cannot create timer\n");
        s_tour.failed = true;
    }
}

/**
 * @brief 巡页是否已经结束（headless 主循环据此提前退出）。
 */
bool sim_ui_tour_done(void)
{
    return s_tour.done || s_tour.failed;
}

/** 是否配置了巡页（供主循环决定等待策略；未配置时行为完全不变）。 */
bool sim_ui_tour_enabled(void)
{
    return s_tour.configured;
}
