static void startup_arm_chore(startup_page_t * ui, unsigned chore)
{
    static const char *const keys[STARTUP_CHORE_COUNT] = {
        "骑行记录", "系统字体", "地图加载"
    };
    static const char *const busy[STARTUP_CHORE_COUNT] = {
        "恢复中", "加载中", "加载中"
    };

    if (ui == NULL || chore >= STARTUP_CHORE_COUNT) {
