    ui->chore = (uint8_t)chore;
    ui->step = STARTUP_STEP_SLIDE_IN;
    ui->chore_t0 = lv_tick_get();
    lv_snprintf(ui->chore_key, sizeof(ui->chore_key), "%s", keys[chore]);
    startup_bar_goal(ui, startup_chore_bar(chore));
