void helm_splash_slide_in(helm_splash_t *s)
{
    if (s == NULL) {
        return;
    }

    s->tick_on = true;
    s->out_busy = false;
    helm_splash_set_chrome_hidden(s, false);
    helm_splash_slide_anim(s, (int32_t)s->stride, 0, 0, 255, false);
