 * @brief 自行车 UI — pm_theme。
 */

#include "lv_pm_theme_def.h"

#include "vmap/vmap_style.h"

static vmap_style_id_t pm_theme_to_vmap(lv_pm_theme_id_t id)
{
    /* ⚠ 判据必须跟**调色板**同源（`helm_palette_follow_theme()`：classic=日光、其余=夜间）：
     * 原来只把 id==1（outdoor）当深色 ⇒ **night(2) 落到 classic（浅色地图）** ——
     * 深色界面配浅色地图，观感割裂。现在"不是 classic 就是深色"，三个主题一条规则。
     * （注：vmap 的 outdoor 枚举值是 2，跟 pm 的 id 不是一回事。） */
    if (id != 0u) {
        return VMAP_STYLE_OUTDOOR;
    }

    return VMAP_STYLE_CLASSIC;
}

/**
 * @brief 自行车 pm theme on activate。
 */
void bicycle_pm_theme_on_activate(lv_pm_theme_id_t id, void * user_data)
{
    (void)user_data;
    vmap_style_set_id(pm_theme_to_vmap(id));
}

void helm_splash_set_gray(helm_splash_t *s, uint8_t g)
{
    uint8_t ink;
    uint8_t track;

    if (s == NULL || s->root == NULL) {
        return;
    }

    s->gray = g;
    ink = (uint8_t)(255u - g);
    track = (uint8_t)(0x38u + ((uint16_t)g * (0xD0u - 0x38u)) / 255u);

    lv_obj_set_style_bg_color(s->root, lv_color_make(g, g, g), 0);
    lv_obj_set_style_bg_opa(s->root, LV_OPA_COVER, 0);

    if (s->clip != NULL) {
        lv_obj_set_style_bg_color(s->clip, lv_color_make(g, g, g), 0);
        lv_obj_set_style_bg_opa(s->clip, LV_OPA_COVER, 0);
    }

    if (s->name != NULL) {
        lv_obj_set_style_text_color(s->name, lv_color_make(ink, ink, ink), 0);
    }

    if (s->lab != NULL) {
        lv_obj_set_style_text_color(s->lab, lv_color_make(ink, ink, ink), 0);
    }

    if (s->bar != NULL) {
        lv_obj_set_style_bg_color(s->bar, lv_color_make(track, track, track), 0);
    }

    if (s->bar_fill != NULL) {
        lv_obj_set_style_bg_color(s->bar_fill, lv_color_make(ink, ink, ink), 0);
    }
}

